// Generated by `rekindle build`; do not edit.
//
// Adapts the JS runtime to the plugin sandbox before the plugin's own code
// runs. The component has no WASI: the engine's clock, entropy and stdio
// imports are stubs that trap, which would fault the plugin with no hint of
// why. So the globals that would reach them are replaced:
//
// - `console.*` goes to the host log. Messages from top-level code (which runs
//   at build time, when there is no host) are held and logged on activate
//   (the render isolate, which never activates, drops them: the main
//   instance already logged them).
// - `setTimeout`/`setInterval` (and their `clear*`) run on the host's timers,
//   so they share its limits: 16 active per plugin, 50 ms minimum.
// - `performance.now()` is the host's monotonic clock.
// - `Date.now()` and `new Date()` throw a clear error: the host has no wall
//   clock, by design (no fingerprinting). Dates built from a value still work.
// - `Math.random()` is reseeded on activate, so it differs between sessions
//   (the engine's own seed is fixed at build time). Not cryptographic.
// - `crypto.getRandomValues()`/`randomUUID()` throw: there's no entropy source.

import { clearTimer, log, nowMillis, setTimer } from 'rekindle:plugin/host@0.8.0';

let live = false;
const held = [];

function show(v) {
  if (typeof v === 'string') return v;
  if (v instanceof Error) return v.stack ? `${v}\n${v.stack}` : String(v);
  try {
    const s = JSON.stringify(v, (_, x) => (typeof x === 'bigint' ? `${x}n` : x));
    return s === undefined ? String(v) : s;
  } catch {
    return String(v);
  }
}

export function emit(level, message) {
  if (live) log(level, message);
  else held.push([level, message]);
}

const levels = { trace: 'trace', debug: 'debug', log: 'info', info: 'info', warn: 'warn', error: 'error' };
// Exported too: the bundler binds plugin code's `console` to this, instead
// of jco's Node console (which would import a host interface rekindle lacks).
export const console = Object.fromEntries(
  Object.entries(levels).map(([name, level]) => [name, (...args) => emit(level, args.map(show).join(' '))]),
);
globalThis.console = console;

// Timers, keyed by host timer ids under a prefix the entry's `onTimer` routes
// here (see entry.mjs).
export const TIMER_PREFIX = 'rekindle:timer:';
const timers = new Map();
let nextTimer = 1;

function schedule(repeat, callback, ms, args) {
  if (typeof callback !== 'function') throw new TypeError('timer callback must be a function');
  const handle = nextTimer++;
  const id = `${TIMER_PREFIX}${handle}`;
  // The host's floor is 50 ms; a plain `setTimeout(f)` means "soon".
  setTimer(id, BigInt(Math.max(50, Math.ceil(Number(ms) || 0))), repeat);
  timers.set(id, { run: () => callback(...args), repeat });
  return handle;
}

function cancel(handle) {
  const id = `${TIMER_PREFIX}${handle}`;
  if (timers.delete(id)) clearTimer(id);
}

export const setTimeout = (callback, ms, ...args) => schedule(false, callback, ms, args);
export const setInterval = (callback, ms, ...args) => schedule(true, callback, ms, args);
export const clearTimeout = cancel;
export const clearInterval = cancel;
Object.assign(globalThis, { setTimeout, setInterval, clearTimeout, clearInterval });

/** Run a prelude timer (an `onTimer` id under `TIMER_PREFIX`). */
export function fireTimer(id) {
  const t = timers.get(id);
  if (!t) return;
  if (!t.repeat) timers.delete(id);
  t.run();
}

globalThis.performance = { now: () => Number(nowMillis()), timeOrigin: 0 };

const noClock = (what) => {
  throw new Error(`${what}: rekindle plugins have no wall clock; use performance.now() for elapsed time`);
};
// A proxy rather than a subclass, so `Date()` called as a function is caught
// too, and `instanceof Date` still holds for every date.
const HostDate = Date;
globalThis.Date = new Proxy(HostDate, {
  apply: () => noClock('Date()'),
  construct(target, args, newTarget) {
    if (args.length === 0) noClock('new Date()');
    return Reflect.construct(target, args, newTarget);
  },
  get(target, key, receiver) {
    if (key === 'now') return () => noClock('Date.now()');
    return Reflect.get(target, key, receiver);
  },
});

// No entropy source: randomness from `crypto` (and `node:crypto`, which uses
// it) fails clearly. Hashing (`crypto.subtle`, where the engine has it) stays.
const noEntropy = (what) => () => {
  throw new Error(`${what}: rekindle plugins have no entropy source`);
};
// StarlingMonkey's `crypto` is a getter-only global: patch the object it
// returns rather than replacing it.
const webCrypto = globalThis.crypto ?? {};
for (const name of ['getRandomValues', 'randomUUID']) {
  Object.defineProperty(webCrypto, name, { value: noEntropy(`crypto.${name}()`), configurable: true, writable: true });
}
if (!globalThis.crypto) globalThis.crypto = webCrypto;

// sfc32 (32-bit arithmetic, no BigInt), seeded on activate.
let a = 0x9e3779b9, b = 0x243f6a88, c = 0xb7e15162, d = 1;
Math.random = () => {
  const t = (((a + b) | 0) + d) | 0;
  d = (d + 1) | 0;
  a = b ^ (b >>> 9);
  b = (c + (c << 3)) | 0;
  c = (c << 21) | (c >>> 11);
  c = (c + t) | 0;
  return (t >>> 0) / 4294967296;
};

/** Called first thing in `activate`. */
export function goLive() {
  live = true;
  for (const [level, message] of held.splice(0)) log(level, message);
  reseed();
}

/**
 * Called first thing in each render-isolate hook (`on-render`,
 * `on-notification`): the isolate never activates.
 */
export function isolateLive() {
  if (live) return;
  live = true;
  held.length = 0;
  reseed();
}

function reseed() {
  const seed = Number(nowMillis()) >>> 0;
  a = seed ^ 0x9e3779b9;
  b = Math.imul(seed, 0x85ebca6b);
  c = Math.imul(seed ^ (seed >>> 16), 0xc2b2ae35);
  d = 1;
  for (let i = 0; i < 12; i++) Math.random();
}
